style.css:
@-moz-document domain("music.amazon.co.jp"), domain("music.amazon.com") {
/* 歌詞表示部分のテキストをターゲットにします */
    /* 選択された歌詞の行 */
    .lyrics-current-line {
        font-size: 2.2rem !important; /* 適切なサイズに調整 */
    }

    /* 前後の歌詞の行 */
    .lyrics-previous-line, .lyrics-next-line {
        font-size: 1.5rem !important; /* 適切なサイズに調整 */
    }

    /* 歌詞全体を囲むコンテナ */
    .web-player-lyrics-container {
        font-family: "Noto Sans JP", sans-serif !important; /* フォントの変更も可能 */
    }
}
